import { getFullMedia } from "@/lib/server-api";
import BackButton from "@/components/BackButton";
import MovieDetails from "@/components/MovieDetails";
import MusicDetails from "@/components/MusicDetails";
import MusicPoster from "@/components/MusicPoster";
import AddToWatchPop from "@/components/AddToWatchpopButton";

export default async function MediaPage({
  params,
}: {
  params: Promise<{ type: string; id: string }>;
}) {
  const { type, id } = await params;
  const media = await getFullMedia(type, id);

  const isAdded = !!media.user_entry;
  const friends =
    typeof media.user_entry?.friends_recommended === "string"
      ? media.user_entry.friends_recommended
          .split(",")
          .map((f: string) => f.trim())
          .filter(Boolean)
      : [];

  const tags =
    typeof media.user_entry?.my_tags === "string"
      ? media.user_entry.my_tags
          .split(",")
          .map((t: string) => t.trim())
          .filter(Boolean)
      : [];
  const highResPoster = media.poster?.replace("100x100bb.jpg", "600x600bb.jpg");

  return (
    <div className="relative max-w-6xl mx-auto px-6 md:px-8 pt-8 pb-32 text-zinc-100">
      {/* Background */}

      {media.poster && (
        <div
          className="absolute inset-0 -z-10 bg-cover bg-center opacity-10 blur-3xl"
          style={{ backgroundImage: `url(${media.poster})` }}
        />
      )}
      <div className="absolute inset-0 -z-10 bg-gradient-to-b from-black/40 via-black/70 to-black" />

      {/* Back Button */}
      <div className="mb-10">
        <BackButton />
      </div>

      {/* HERO */}
      <section className="grid md:grid-cols-[260px_1fr] gap-12 items-start">
        {/* LEFT COLUMN */}
        <div className="space-y-6">
          {media.poster && (
            <div className="relative">
              <img
                src={highResPoster || media.poster}
                alt={media.title}
                className="w-[260px] md:w-[280px] rounded-2xl object-cover shadow-xl"
              />
              <div className="absolute inset-0 rounded-2xl ring-1 ring-white/10" />
            </div>
          )}

          {/* Personal Tags */}
          {tags.length > 0 && (
            <div>
              <p className="text-xs tracking-widest uppercase text-zinc-500 mb-3">
                Your Tags
              </p>

              <div className="flex flex-wrap gap-2">
                {tags.map((tag: string) => (
                  <a
                    key={tag}
                    href={`#`}
                    className="px-3 py-1 text-xs rounded-full
                         bg-white/5 border border-white/10
                         hover:bg-white/10 transition"
                  >
                    #{tag}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Content */}
        <div className="max-w-2xl space-y-6">
          {/* Title Block */}
          <div className="space-y-3">
            <h1 className="text-4xl md:text-[44px] font-semibold tracking-tight leading-tight">
              {media.title}
            </h1>

            {media.subtitle && (
              <p className="text-zinc-400 text-base">{media.subtitle}</p>
            )}
          </div>

          {/* Meta */}
          <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm text-zinc-500">
            {media.genre && <span>{media.genre}</span>}
            {media.release_date && <span>{media.release_date}</span>}
          </div>

          {/* Rating + Recommended */}
          {media.user_entry && (
            <div className="space-y-5">
              {media.user_entry.rating && (
                <div>
                  <div className="mb-1 text-xs tracking-widest uppercase text-zinc-500">
                    Rating
                  </div>

                  <div className="flex gap-1">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span
                        key={star}
                        className={`text-lg ${
                          star <= media.user_entry.rating
                            ? "text-yellow-400/80"
                            : "text-zinc-600"
                        }`}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {friends.length > 0 && (
                <div>
                  <div className="mb-2 text-xs tracking-widest uppercase text-zinc-500">
                    Recommended By
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {friends.map((f: string) => (
                      <a
                        key={f}
                        href={`/recommended?friends_recommended=${encodeURIComponent(f)}`}
                        className="px-3 py-1 text-xs rounded-full
                             bg-white/5 border border-white/10
                             hover:bg-white/10 transition"
                      >
                        {f}
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Add Button */}
          <div className="pt-2">
            <AddToWatchPop
              item={{ id, title: media.title }}
              type={type as "movie" | "music"}
              isAdded={isAdded}
            />
          </div>
        </div>
      </section>

      {/* OVERVIEW */}
      {media.description && (
        <section className="mt-12 max-w-4xl">
          <div className="border-t border-zinc-800 pt-12">
            <p className="text-xs tracking-widest text-zinc-500 uppercase mb-8">
              Overview
            </p>

            <p className="text-zinc-400 leading-relaxed text-[15px]">
              {media.description}
            </p>
          </div>
        </section>
      )}

      {/* TYPE-SPECIFIC DETAILS */}
      <section className="mt-16 space-y-16">
        {type === "movie" && <MovieDetails data={media.provider_data} />}
        {type === "music" && <MusicDetails data={media.provider_data} />}
      </section>
    </div>
  );
}
